add_action( 'wp', 'perfectpixel_remove_sidebar_product_page' );
add_filter( 'body_class', 'perfectpixel_remove_sidebar_product_body_class' );

function perfectpixel_remove_sidebar_product_page() {
	if ( function_exists( 'is_product' ) && is_product() ) {
		remove_action( 'woocommerce_sidebar', 'woocommerce_get_sidebar', 10 );
		remove_action( 'storefront_sidebar', 'storefront_get_sidebar', 10 );
	}
}

// Storefront switches to its full-width layout with this class.
function perfectpixel_remove_sidebar_product_body_class( $classes ) {
	if ( function_exists( 'is_product' ) && is_product() ) {
		$classes[] = 'storefront-full-width-content';
	}
	return $classes;
}
